@Transactional
public Sheet setDefaultGrade(String sheetId, String by, String grade) {
    if (grade != null && !grade.matches("[ABC]") && !addedGrades.existsBySheetIdAndGrade(sheetId, grade)) {
        throw new IllegalArgumentException("A default grade is one of the sheet's grades, not " + grade);
    }
    sheets.load(sheetId);
    Sheet sheet = sheetRepository.findLockedById(sheetId).orElseThrow();
    sheet.setDefaultGrade(grade);
    Sheet saved = sheetRepository.saveAndFlush(sheet);
    history.settingSet(sheetId, DEFAULT_GRADE, grade);
    audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=default-grade value="
            + (grade != null ? grade : ""));
    return saved;
}

/** Change the sheet's review SLA; null leaves it blank (none). */
@Transactional
public Sheet setReviewSla(String sheetId, String by, Integer days) {
